control_plane.guard_personal_credential_.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_personal_credential_test()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control_plane'
AS $function$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'personal credential test history cannot be deleted' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.state<>'DUE' OR NEW.generation<>0 OR NEW.version<>1 THEN
            RAISE EXCEPTION 'personal credential test initial state is invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.id,NEW.ref,NEW.organization_id,NEW.connection_id,NEW.binding_id,NEW.subject_id,NEW.credential_revision_id,NEW.input_schema_version,NEW.input_snapshot,NEW.created_at)
       IS DISTINCT FROM
       (OLD.id,OLD.ref,OLD.organization_id,OLD.connection_id,OLD.binding_id,OLD.subject_id,OLD.credential_revision_id,OLD.input_schema_version,OLD.input_snapshot,OLD.created_at) OR
       OLD.version=9223372036854775807 OR NEW.version<>OLD.version+1 OR NOT (
        (OLD.state='DUE' AND NEW.state='CLAIMED' AND NEW.generation=1) OR
        (OLD.state='DUE' AND NEW.state='CANCELLED' AND NEW.generation=0) OR
        (OLD.state='CLAIMED' AND NEW.state IN ('PROBING','FAILED','CANCELLED') AND NEW.generation=OLD.generation) OR
        (OLD.state='PROBING' AND NEW.state IN ('SUCCEEDED','FAILED','CANCELLED') AND NEW.generation=OLD.generation)
       ) OR (OLD.probe_admitted_at IS NOT NULL AND NEW.probe_admitted_at IS DISTINCT FROM OLD.probe_admitted_at) OR
       (OLD.probe_admitted_at IS NULL AND NEW.probe_admitted_at IS NOT NULL AND NOT (OLD.state='CLAIMED' AND NEW.state='PROBING')) OR
       (OLD.state='CLAIMED' AND NEW.state='PROBING' AND
        (NEW.lease_ref,NEW.fence_digest,NEW.workload_instance,NEW.lease_expires_at) IS DISTINCT FROM
        (OLD.lease_ref,OLD.fence_digest,OLD.workload_instance,OLD.lease_expires_at)) THEN
        RAISE EXCEPTION 'personal credential test transition is invalid' USING ERRCODE='23514';
    END IF;
    NEW.updated_at:=clock_timestamp();
    RETURN NEW;
END;
$function$

control_plane.guard_personal_integration.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_personal_integration_credential()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control_plane'
AS $function$
DECLARE
    credential_changed boolean;
    newly_revoked boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'personal integration credential history cannot be deleted' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'NOT_CONFIGURED' OR NEW.version <> 1 OR NEW.generation <> 1 OR
           NEW.credential_revision_id IS NOT NULL THEN
            RAISE EXCEPTION 'personal integration credential initial state is invalid' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.id, NEW.ref, NEW.organization_id, NEW.connection_id, NEW.subject_id, NEW.created_at)
       IS DISTINCT FROM
       (OLD.id, OLD.ref, OLD.organization_id, OLD.connection_id, OLD.subject_id, OLD.created_at) OR
       OLD.version = 9223372036854775807 OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'personal integration credential owner or version is invalid' USING ERRCODE = '23514';
    END IF;
    credential_changed := NEW.credential_revision_id IS DISTINCT FROM OLD.credential_revision_id;
    newly_revoked := NEW.state = 'REVOKED' AND OLD.state <> 'REVOKED';
    IF credential_changed OR newly_revoked THEN
        IF OLD.generation = 9223372036854775807 OR NEW.generation <> OLD.generation + 1 OR
           NEW.state NOT IN ('CHECK_REQUIRED', 'REVOKED') OR
           (credential_changed AND (NEW.state <> 'CHECK_REQUIRED' OR NEW.credential_revision_id IS NULL)) THEN
            RAISE EXCEPTION 'personal integration credential generation is invalid' USING ERRCODE = '23514';
        END IF;
        IF credential_changed AND OLD.credential_revision_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM control_plane.integration_personal_credential_revisions previous_revision
            JOIN control_plane.integration_personal_credential_revisions next_revision
              ON next_revision.binding_id = previous_revision.binding_id
             AND next_revision.organization_id = previous_revision.organization_id
             AND next_revision.revision > previous_revision.revision
            WHERE previous_revision.id = OLD.credential_revision_id
              AND next_revision.id = NEW.credential_revision_id
              AND previous_revision.binding_id = OLD.id
              AND previous_revision.organization_id = OLD.organization_id
        ) THEN
            RAISE EXCEPTION 'personal integration credential revision must advance' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.generation <> OLD.generation OR NOT (
        (OLD.state IN ('CHECK_REQUIRED', 'READY', 'INVALID') AND NEW.state = 'CHECKING') OR
        (OLD.state IN ('READY', 'INVALID') AND NEW.state = 'CHECK_REQUIRED') OR
        (OLD.state = 'CHECKING' AND NEW.state IN ('READY', 'INVALID', 'CHECK_REQUIRED'))
    ) THEN
        RAISE EXCEPTION 'personal integration credential transition is invalid' USING ERRCODE = '23514';
    END IF;
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
END;
$function$

control_plane.guard_ssh_compose_snapshot.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_ssh_compose_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF OLD.ssh_compose_snapshot IS NOT NULL AND OLD.ssh_compose_snapshot IS DISTINCT FROM NEW.ssh_compose_snapshot THEN
    RAISE EXCEPTION 'SSH Compose snapshot is immutable';
  END IF;
  RETURN NEW;
END;
$function$

control_plane.guard_workflow_exception_e.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_workflow_exception_episodes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control_plane'
AS $function$
DECLARE old_count integer; new_count integer; previous jsonb; episode jsonb; immutable_keys text[];
        terminal boolean; published jsonb;
BEGIN
    IF TG_OP='DELETE' THEN
        IF OLD.workflow_exception_history<>'[]'::jsonb OR OLD.workflow_exception IS NOT NULL THEN
            IF NOT control_plane.project_purge_authorized() OR NOT EXISTS (
                SELECT 1 FROM control_plane.project_purge_targets target
                JOIN control_plane.project_purge_context context USING (transaction_id)
                WHERE target.transaction_id=pg_current_xact_id_if_assigned() AND context.backend_pid=pg_backend_pid()
                    AND target.relation_id='control_plane.runs'::regclass AND target.row_key=jsonb_build_array(OLD.id)
            ) THEN
                RAISE EXCEPTION 'workflow exception history requires authorized project purge'
                    USING ERRCODE='23514', CONSTRAINT='workflow_exception_delete_authority';
            END IF;
        END IF;
        RETURN OLD;
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.workflow_exception_history<>'[]'::jsonb OR NEW.workflow_exception IS NOT NULL THEN
            RAISE EXCEPTION 'workflow exception history must start empty' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    terminal:=NEW.state IN ('FAILED','CANCELLED');
    old_count:=jsonb_array_length(OLD.workflow_exception_history);
    IF terminal AND OLD.workflow_exception IS NOT NULL AND old_count>0 THEN
        episode:=OLD.workflow_exception_history->-1;
        IF episode->>'state' IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER') THEN
            episode:=episode||jsonb_build_object('state',CASE WHEN EXISTS (
                    SELECT 1 FROM control_plane.owner_gates decision_gate
                    WHERE decision_gate.id::text=episode->>'gateId' AND decision_gate.ref=episode->>'gateRef'
                        AND decision_gate.organization_id=NEW.organization_id AND decision_gate.root_run_id=NEW.id
                        AND decision_gate.project_id=NEW.project_id
                        AND decision_gate.state='REJECTED' AND decision_gate.decision='REJECT'
                ) THEN 'REJECTED' ELSE 'CANCELLED' END,
                'version',(episode->>'version')::bigint+1);
            NEW.workflow_exception_history:=jsonb_set(OLD.workflow_exception_history,ARRAY[(old_count-1)::text],episode);
            NEW.workflow_exception:=NULL;
        END IF;
    END IF;
    IF NEW.workflow_exception_history IS NOT DISTINCT FROM OLD.workflow_exception_history
       AND NEW.workflow_exception IS NOT DISTINCT FROM OLD.workflow_exception THEN
        IF NEW.state='SUCCEEDED' AND NEW.workflow_exception IS NOT NULL THEN
            RAISE EXCEPTION 'workflow recovery blocks successful root completion' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id IS DISTINCT FROM NEW.root_run_id OR jsonb_typeof(NEW.workflow_exception_history) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'workflow episodes belong to one root' USING ERRCODE='23514';
    END IF;
    SELECT version.spec INTO published FROM control_plane.workflow_versions version
    JOIN control_plane.workflows workflow ON workflow.id=version.workflow_id AND workflow.organization_id=version.organization_id
    WHERE version.id=NEW.workflow_version_id AND version.organization_id=NEW.organization_id
        AND workflow.project_id=NEW.project_id AND version.spec->>'ExecutionMode'='SERVER_DAG_V1';
    IF published IS NULL THEN RAISE EXCEPTION 'workflow episode requires pinned server policy' USING ERRCODE='23514'; END IF;
    new_count:=jsonb_array_length(NEW.workflow_exception_history);
    IF new_count<1 OR new_count>48 OR new_count<old_count OR new_count>old_count+1 OR EXISTS (
        SELECT 1 FROM jsonb_array_elements(OLD.workflow_exception_history) WITH ORDINALITY item(value,position)
        WHERE item.position<=LEAST(old_count,new_count-1) AND NEW.workflow_exception_history->(item.position::integer-1) IS DISTINCT FROM item.value
    ) THEN RAISE EXCEPTION 'workflow episode prefix is immutable' USING ERRCODE='23514'; END IF;
    episode:=NEW.workflow_exception_history->-1;
    IF jsonb_typeof(episode) IS DISTINCT FROM 'object'
       OR episode-ARRAY['stepKey','attempt','reason','originNodeId','finalNodeId','episode','version','state',
           'managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId','inputs','kind','reworkPlan']<>'{}'::jsonb
       OR NOT episode ?& ARRAY['stepKey','attempt','reason','originNodeId','finalNodeId','episode','version','state','inputs']
       OR episode->'episode' IS DISTINCT FROM to_jsonb(new_count)
       OR jsonb_typeof(episode->'inputs') IS DISTINCT FROM 'array'
       OR jsonb_array_length(episode->'inputs')>8
       OR jsonb_typeof(episode->'state') IS DISTINCT FROM 'string'
       OR jsonb_typeof(episode->'attempt') IS DISTINCT FROM 'number'
       OR jsonb_typeof(episode->'version') IS DISTINCT FROM 'number'
       OR jsonb_typeof(episode->'reason') IS DISTINCT FROM 'string'
       OR (episode->>'reason')!~'^[A-Z_]{1,96}$'
       OR episode->>'state' NOT IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER','RECOVERED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'workflow episode shape is invalid' USING ERRCODE='23514';
    END IF;
    IF (episode ? 'kind') IS DISTINCT FROM (episode ? 'reworkPlan')
        OR (episode ? 'kind' AND (episode->>'kind'<>'UPSTREAM_REWORK' OR published->>'ReworkPolicy' IS DISTINCT FROM 'OWNER_APPROVED_UPSTREAM_V1')) THEN
        RAISE EXCEPTION 'workflow rework requires the explicit published profile' USING ERRCODE='23514';
    END IF;
    IF new_count=old_count+1 AND episode ? 'kind' AND control_plane.workflow_upstream_plan_valid(NEW.organization_id,NEW.id,episode) IS NOT TRUE THEN
        RAISE EXCEPTION 'workflow upstream plan differs from exact published subjects' USING ERRCODE='23514';
    END IF;
    IF new_count=old_count+1 THEN
        IF old_count>0 AND (OLD.workflow_exception IS NOT NULL OR OLD.workflow_exception_history->-1->>'state' NOT IN ('RECOVERED','REJECTED','CANCELLED')) THEN
            RAISE EXCEPTION 'workflow episode already active' USING ERRCODE='23514';
        END IF;
        IF episode->'version' IS DISTINCT FROM '1'::jsonb OR episode->>'state'<>'PENDING_MANAGER'
           OR episode ?| ARRAY['managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId']
           OR (episode->>'attempt')::integer NOT BETWEEN 0 AND 4 OR NOT EXISTS (
            SELECT 1 FROM control_plane.run_nodes anchor
            JOIN control_plane.run_nodes physical ON physical.id::text=episode->>'finalNodeId'
                AND physical.organization_id=anchor.organization_id AND physical.root_run_id=anchor.root_run_id
            WHERE anchor.organization_id=NEW.organization_id AND anchor.root_run_id=NEW.id
                AND anchor.id::text=episode->>'originNodeId' AND anchor.workflow_step_origin_node_id IS NULL
                AND anchor.workflow_step_key=episode->>'stepKey'
                AND ((episode->>'attempt'='0' AND anchor.id=physical.id AND anchor.workflow_business_attempt=0
                    AND anchor.state='PLANNED' AND anchor.materialization_state='PLANNED')
                  OR (episode->>'attempt'<>'0' AND COALESCE(physical.workflow_step_origin_node_id,physical.id)=anchor.id
                    AND physical.workflow_business_attempt=(episode->>'attempt')::integer
                    AND physical.workflow_inputs=episode->'inputs'
                    AND jsonb_array_length(anchor.workflow_attempts)=(episode->>'attempt')::integer
                    AND anchor.workflow_attempts->-1->'provenance'->>'nodeId'=physical.id::text
                    AND (anchor.workflow_attempts->-1->>'reason'=episode->>'reason'
                         OR (episode->>'reason'='OWNER_CHANGES_REQUESTED' AND anchor.workflow_attempts->-1->>'accepted'='true'))))
        ) THEN RAISE EXCEPTION 'workflow episode requires exact current attempt' USING ERRCODE='23514'; END IF;
    ELSE
        previous:=OLD.workflow_exception_history->-1;
        immutable_keys:=ARRAY['version','state','managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId'];
        IF episode-immutable_keys IS DISTINCT FROM previous-immutable_keys
           OR episode->'version' IS DISTINCT FROM to_jsonb((previous->>'version')::bigint+1)
           OR NOT ((previous->>'state'='PENDING_MANAGER' AND episode->>'state' IN ('MANAGER_QUEUED','WAITING_OWNER'))
               OR (previous->>'state'='MANAGER_QUEUED' AND episode->>'state'='WAITING_OWNER')
               OR (previous->>'state'='WAITING_OWNER' AND episode->>'state'='RECOVERED')
               OR (terminal AND previous->>'state' IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER')
                   AND episode->>'state' IN ('REJECTED','CANCELLED')))
           OR EXISTS (SELECT 1 FROM unnest(ARRAY['managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId']) pin
               WHERE previous ? pin AND episode->pin IS DISTINCT FROM previous->pin) THEN
            RAISE EXCEPTION 'workflow episode transition or pins changed' USING ERRCODE='23514';
        END IF;
    END IF;
    IF episode->>'state' IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER') THEN
        IF NEW.workflow_exception IS DISTINCT FROM episode OR NEW.state NOT IN ('QUEUED','RUNNING','WAITING_HUMAN') THEN
            RAISE EXCEPTION 'workflow active episode pin differs' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.workflow_exception IS NOT NULL THEN RAISE EXCEPTION 'workflow terminal episode remains active' USING ERRCODE='23514'; END IF;
    IF episode ? 'managerNodeId' AND NOT EXISTS (
        SELECT 1 FROM control_plane.run_nodes node
        JOIN control_plane.agents agent ON agent.id=node.agent_id AND agent.organization_id=node.organization_id AND agent.project_id=NEW.project_id
        WHERE node.organization_id=NEW.organization_id AND node.root_run_id=NEW.id
            AND node.id::text=episode->>'managerNodeId' AND node.ref=episode->>'managerNodeRef'
            AND node.workflow_step_key='workflow.coordinator.exception.'||(episode->>'episode')
            AND node.workflow_business_attempt=0 AND agent.ref=published->>'CoordinatorAgentRef'
    ) THEN RAISE EXCEPTION 'workflow manager pin differs' USING ERRCODE='23514'; END IF;
    IF episode->>'state'='WAITING_OWNER' AND episode ? 'managerNodeId' AND NOT EXISTS (
        SELECT 1 FROM control_plane.run_nodes node
        JOIN control_plane.runtime_revisions revision ON revision.node_id=node.id AND revision.organization_id=node.organization_id
            AND revision.run_id=node.run_id AND revision.root_run_id=node.root_run_id AND revision.turn_id=node.turn_id
            AND revision.agent_id=node.agent_id AND revision.attempt=node.attempt
        JOIN control_plane.runtime_leases lease ON lease.runtime_revision_id=revision.id AND lease.organization_id=revision.organization_id
            AND lease.run_id=revision.run_id AND lease.node_id=node.id AND lease.generation=revision.generation AND lease.state='COMPLETED'
        WHERE node.organization_id=NEW.organization_id AND node.root_run_id=NEW.id AND node.id::text=episode->>'managerNodeId'
            AND node.state IN ('SUCCEEDED','FAILED')
    ) THEN RAISE EXCEPTION 'workflow manager is not completed' USING ERRCODE='23514'; END IF;
    IF episode->>'state'='WAITING_OWNER' AND NOT EXISTS (
        SELECT 1 FROM control_plane.owner_gates gate
        JOIN control_plane.run_nodes gate_node ON gate_node.id=gate.node_id AND gate_node.organization_id=gate.organization_id
        WHERE gate.organization_id=NEW.organization_id AND gate.root_run_id=NEW.id AND gate.project_id=NEW.project_id
            AND gate.id::text=episode->>'gateId' AND gate.ref=episode->>'gateRef' AND gate.state='OPEN'
            AND gate_node.parent_node_id::text=COALESCE(episode->>'managerNodeId',episode->>'finalNodeId')
    ) THEN RAISE EXCEPTION 'workflow recovery gate pin differs' USING ERRCODE='23514'; END IF;
    IF episode->>'state'='RECOVERED' AND NOT EXISTS (
        SELECT 1 FROM control_plane.run_nodes node
        JOIN control_plane.owner_gates gate ON gate.id::text=episode->>'gateId'
            AND gate.organization_id=NEW.organization_id AND gate.root_run_id=NEW.id AND gate.state='APPROVED'
        WHERE node.id::text=episode->>'recoveryNodeId' AND node.organization_id=NEW.organization_id AND node.root_run_id=NEW.id
            AND ((NOT episode ? 'kind'
                AND node.workflow_business_attempt=(episode->>'attempt')::integer+1
                AND COALESCE(node.workflow_step_origin_node_id,node.id)::text=episode->>'originNodeId'
                AND node.workflow_inputs=episode->'inputs' AND (episode->>'attempt')::integer<4)
              OR (episode->>'kind'='UPSTREAM_REWORK' AND node.workflow_rework_gate_id=gate.id
                AND node.workflow_business_attempt BETWEEN 2 AND 4
                AND COALESCE(episode->'reworkPlan'->>'blockReason','')=''
                AND EXISTS(SELECT 1 FROM jsonb_array_elements(episode->'reworkPlan'->'targets') member(value)
                    WHERE member.value->>'originNodeId'=node.workflow_step_origin_node_id::text
                        AND member.value->>'stepKey'=node.workflow_step_key
                        AND member.value->'nextAttempt'=to_jsonb(node.workflow_business_attempt))))
            AND (episode->>'episode')::integer<48
    ) THEN RAISE EXCEPTION 'workflow fresh recovery execution differs' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$function$

control_plane.protect_email_mailbox_gate.definition:
CREATE OR REPLACE FUNCTION control_plane.protect_email_mailbox_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP='UPDATE' AND (NEW.mailbox_gate_required IS DISTINCT FROM OLD.mailbox_gate_required
        OR NEW.approval_policy IS DISTINCT FROM OLD.approval_policy
        OR NEW.grant_version IS DISTINCT FROM OLD.grant_version
        OR NEW.approval_scope_paths IS DISTINCT FROM OLD.approval_scope_paths) THEN
        RAISE EXCEPTION 'integration approval binding is immutable';
    END IF;
    IF NEW.mailbox_gate_required OR (NEW.risk<>'READ' AND NEW.approval_policy='NONE' AND NEW.resource_kind='EMAIL_SENDER') THEN
        IF NOT EXISTS (SELECT 1 FROM control_plane.integration_connections c
                       WHERE c.id=NEW.connection_id AND c.organization_id=NEW.organization_id AND c.definition_key='email') THEN
            RAISE EXCEPTION 'mailbox approval requires email owner connection';
        END IF;
    ELSIF NEW.risk<>'READ' AND NEW.approval_policy='NONE' THEN
        IF NEW.risk<>'WRITE' OR NEW.resource_kind<>'GITHUB_REPOSITORY' OR NEW.operation<>NEW.capability_key OR
           NEW.operation NOT IN ('github.issue.comment.create','github.issue.comment.update','github.pull_request.create','github.pull_request.update','github.pull_request.review.create','github.issue.create','github.issue.update','github.repository.content.create','github.repository.content.update','github.pull_request.comment.create','github.pull_request.comment.update','github.pull_request.ready') OR
           NOT EXISTS (SELECT 1 FROM control_plane.integration_connections c
                       WHERE c.id=NEW.connection_id AND c.organization_id=NEW.organization_id AND c.definition_key='github') OR
           (NEW.operation='github.pull_request.review.create' AND NEW.bounded_input->>'event' IS DISTINCT FROM 'COMMENT') THEN
            RAISE EXCEPTION 'autonomous integration write is not allowed';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

control_plane.protect_workflow_execution.definition:
CREATE OR REPLACE FUNCTION control_plane.protect_workflow_execution_clock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control_plane'
AS $function$
DECLARE
    specification jsonb;
    step text;
    seconds integer;
    started timestamptz;
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.execution_started_at IS NOT NULL OR NEW.execution_deadline_at IS NOT NULL
           OR NEW.execution_timeout_seconds IS NOT NULL OR NEW.execution_step_key IS NOT NULL THEN
            RAISE EXCEPTION 'workflow execution clock is assigned on first claim';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.execution_started_at IS NOT NULL THEN
        IF ROW(NEW.execution_started_at,NEW.execution_deadline_at,NEW.execution_timeout_seconds,NEW.execution_step_key,NEW.workflow_version_id)
           IS DISTINCT FROM ROW(OLD.execution_started_at,OLD.execution_deadline_at,OLD.execution_timeout_seconds,OLD.execution_step_key,OLD.workflow_version_id) THEN
            RAISE EXCEPTION 'workflow execution clock is immutable';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.execution_started_at IS NULL THEN
        IF NEW.execution_deadline_at IS NOT NULL OR NEW.execution_timeout_seconds IS NOT NULL OR NEW.execution_step_key IS NOT NULL THEN
            RAISE EXCEPTION 'workflow execution clock is incomplete';
        END IF;
        RETURN NEW;
    END IF;
    SELECT version.spec INTO STRICT specification FROM control_plane.workflow_versions version
    JOIN control_plane.runs root ON root.workflow_version_id=version.id
    WHERE root.id=NEW.root_run_id AND root.organization_id=NEW.organization_id
      AND root.project_id IS NOT DISTINCT FROM NEW.project_id
      AND NEW.workflow_version_id=version.id;
    IF NEW.id=NEW.root_run_id THEN
        step := ''; seconds := (specification->>'TimeoutSeconds')::integer;
    ELSE
        SELECT node.workflow_step_key INTO STRICT step FROM control_plane.run_nodes node
        WHERE node.run_id=NEW.id AND node.organization_id=NEW.organization_id AND node.type='AGENT_EXECUTION';
        SELECT (item->>'TimeoutSeconds')::integer INTO STRICT seconds
        FROM jsonb_array_elements(specification->'Steps') item WHERE item->>'Key'=step;
    END IF;
    IF seconds<1 OR seconds>(CASE WHEN step='' THEN 604800 ELSE 86400 END)
       OR NEW.state NOT IN ('QUEUED','RUNNING') THEN
        RAISE EXCEPTION 'workflow execution clock source is invalid';
    END IF;
    started := clock_timestamp();
    NEW.execution_started_at := started;
    NEW.execution_timeout_seconds := seconds;
    NEW.execution_step_key := step;
    NEW.execution_deadline_at := started+seconds*interval '1 second';
    RETURN NEW;
END $function$

control_plane.purge_project_database(uui.definition:
CREATE OR REPLACE FUNCTION control_plane.purge_project_database(p_organization_id uuid, p_project_id uuid, p_objects_digest text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
    v_transaction_id xid8;
    v_receipt control_plane.project_purge_receipts%ROWTYPE;
    v_project_ref text;
    v_nodes integer;
    v_node_fingerprint text;
    v_edges integer;
    v_edge_fingerprint text;
    v_edge record;
    v_table record;
    v_join text;
    v_row_key text;
    v_added integer;
    v_cycle_added integer;
    v_deleted_rows integer;
    v_bad boolean;
BEGIN
    SELECT * INTO v_receipt
    FROM control_plane.project_purge_receipts
    WHERE organization_id = p_organization_id AND project_id = p_project_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'project purge receipt is missing';
    END IF;
    IF v_receipt.state = 'DONE' THEN
        IF v_receipt.objects_digest IS DISTINCT FROM p_objects_digest THEN
            RAISE EXCEPTION 'project purge receipt digest changed';
        END IF;
        RETURN v_receipt.deleted_rows;
    END IF;
    IF v_receipt.state <> 'OBJECTS_CLEARED' OR
       v_receipt.objects_digest IS DISTINCT FROM p_objects_digest OR
       v_receipt.objects_cleared_at IS NULL THEN
        RAISE EXCEPTION 'project purge external cleanup is unverified';
    END IF;
    SELECT ref INTO v_project_ref FROM control_plane.projects
    WHERE id = p_project_id AND organization_id = p_organization_id
      AND lifecycle = 'PURGE_PENDING'
    FOR UPDATE;
    IF NOT FOUND OR v_project_ref IS DISTINCT FROM v_receipt.project_ref THEN
        RAISE EXCEPTION 'project purge target changed';
    END IF;
    IF control_plane.project_purge_inventory_digest(p_organization_id, p_project_id)
       IS DISTINCT FROM p_objects_digest THEN
        RAISE EXCEPTION 'project purge external inventory changed';
    END IF;

    WITH RECURSIVE nodes(relation_id) AS (
        SELECT 'control_plane.projects'::regclass::oid
        UNION
        SELECT constraint_row.conrelid FROM nodes
        JOIN pg_constraint constraint_row ON constraint_row.contype = 'f'
          AND constraint_row.confrelid = nodes.relation_id
        JOIN pg_namespace namespace_row ON namespace_row.oid = constraint_row.connamespace
          AND namespace_row.nspname = 'control_plane'
    )
    SELECT count(*),
           md5(string_agg(namespace_row.nspname || '.' || class_row.relname,
                          E'\n' ORDER BY namespace_row.nspname, class_row.relname))
    INTO v_nodes, v_node_fingerprint
    FROM nodes JOIN pg_class class_row ON class_row.oid = nodes.relation_id
    JOIN pg_namespace namespace_row ON namespace_row.oid = class_row.relnamespace;
    IF v_nodes <> 111 OR v_node_fingerprint <> '3eb558fae167872ba6bd17bc68f7a303' THEN
        RAISE EXCEPTION 'project purge table graph changed';
    END IF;
    WITH RECURSIVE nodes(relation_id) AS (
        SELECT 'control_plane.projects'::regclass::oid
        UNION
        SELECT constraint_row.conrelid FROM nodes
        JOIN pg_constraint constraint_row ON constraint_row.contype = 'f'
          AND constraint_row.confrelid = nodes.relation_id
        JOIN pg_namespace namespace_row ON namespace_row.oid = constraint_row.connamespace
          AND namespace_row.nspname = 'control_plane'
    )
    SELECT count(*), md5(string_agg(
        child_namespace.nspname || '.' || child_class.relname || '|' ||
        constraint_row.conname || '|' ||
        parent_namespace.nspname || '.' || parent_class.relname || '|' ||
        constraint_row.confdeltype::text,
        E'\n' ORDER BY child_namespace.nspname, child_class.relname, constraint_row.conname))
    INTO v_edges, v_edge_fingerprint
    FROM pg_constraint constraint_row
    JOIN pg_class child_class ON child_class.oid = constraint_row.conrelid
    JOIN pg_namespace child_namespace ON child_namespace.oid = child_class.relnamespace
    JOIN pg_class parent_class ON parent_class.oid = constraint_row.confrelid
    JOIN pg_namespace parent_namespace ON parent_namespace.oid = parent_class.relnamespace
    WHERE constraint_row.contype = 'f'
      AND constraint_row.confrelid IN (SELECT relation_id FROM nodes)
      AND constraint_row.conrelid IN (SELECT relation_id FROM nodes);
    IF v_edges <> 306 OR v_edge_fingerprint <> '19782286a860f9e05cdaad7b6e5f8ef3' THEN
        RAISE EXCEPTION 'project purge foreign-key graph changed';
    END IF;


    IF EXISTS (
      WITH RECURSIVE nodes(relation_id) AS (
        SELECT 'control_plane.projects'::regclass::oid UNION
        SELECT c.conrelid FROM nodes n JOIN pg_constraint c ON c.confrelid=n.relation_id
          AND c.contype='f' AND c.connamespace='control_plane'::regnamespace
      ) SELECT 1 FROM pg_constraint WHERE contype='f' AND confdeltype='a' AND NOT condeferrable
        AND conrelid IN(SELECT relation_id FROM nodes) AND confrelid IN(SELECT relation_id FROM nodes)
    ) THEN RAISE EXCEPTION 'project purge deferred foreign-key graph changed'; END IF;
    v_transaction_id := pg_current_xact_id();
    INSERT INTO control_plane.project_purge_context(transaction_id, backend_pid, project_id)
    VALUES (v_transaction_id, pg_backend_pid(), p_project_id);

    PERFORM control_plane.project_purge_recovery_prepare_purge(p_organization_id,p_project_id,p_objects_digest);

    UPDATE control_plane.audit_events event
    SET assistant_agent_id=NULL
    FROM control_plane.agents agent
    WHERE event.organization_id=p_organization_id AND event.assistant_agent_id=agent.id
      AND agent.organization_id=p_organization_id AND agent.project_id=p_project_id
      AND event.project_id IS DISTINCT FROM p_project_id;


    INSERT INTO control_plane.project_purge_targets(
        transaction_id, relation_id, row_tid, row_key
    )
    SELECT v_transaction_id, project.tableoid::oid, project.ctid,
           jsonb_build_array(project.id)
    FROM control_plane.projects project
    WHERE project.id = p_project_id AND project.organization_id = p_organization_id;
    SET CONSTRAINTS ALL DEFERRED;

    LOOP
        v_cycle_added := 0;
        FOR v_edge IN
            SELECT constraint_row.conrelid, constraint_row.confrelid,
                   constraint_row.conkey, constraint_row.confkey,
                   format('%I.%I', child_namespace.nspname, child_class.relname) AS child_table,
                   format('%I.%I', parent_namespace.nspname, parent_class.relname) AS parent_table
            FROM pg_constraint constraint_row
            JOIN pg_class child_class ON child_class.oid = constraint_row.conrelid
            JOIN pg_namespace child_namespace ON child_namespace.oid = child_class.relnamespace
            JOIN pg_class parent_class ON parent_class.oid = constraint_row.confrelid
            JOIN pg_namespace parent_namespace ON parent_namespace.oid = parent_class.relnamespace
            WHERE constraint_row.contype = 'f'
              AND child_namespace.nspname = 'control_plane'
              AND parent_namespace.nspname = 'control_plane'
              AND constraint_row.confrelid IN (
                  SELECT DISTINCT relation_id FROM control_plane.project_purge_targets
                  WHERE transaction_id = v_transaction_id)
            ORDER BY constraint_row.conrelid, constraint_row.conname
        LOOP
            SELECT string_agg(format('child.%I = parent.%I', child_attribute.attname,
                                     parent_attribute.attname), ' AND ' ORDER BY child_column.n)
            INTO v_join
            FROM unnest(v_edge.conkey) WITH ORDINALITY AS child_column(number, n)
            JOIN unnest(v_edge.confkey) WITH ORDINALITY AS parent_column(number, n)
              ON parent_column.n = child_column.n
            JOIN pg_attribute child_attribute ON child_attribute.attrelid = v_edge.conrelid
              AND child_attribute.attnum = child_column.number
            JOIN pg_attribute parent_attribute ON parent_attribute.attrelid = v_edge.confrelid
              AND parent_attribute.attnum = parent_column.number;
            IF v_join IS NULL THEN
                RAISE EXCEPTION 'project purge foreign-key columns changed';
            END IF;
            SELECT string_agg(format('child.%I', key_attribute.attname), ', ' ORDER BY key_column.n)
            INTO v_row_key
            FROM pg_constraint primary_key
            CROSS JOIN LATERAL unnest(primary_key.conkey) WITH ORDINALITY AS key_column(number, n)
            JOIN pg_attribute key_attribute ON key_attribute.attrelid = primary_key.conrelid
              AND key_attribute.attnum = key_column.number
            WHERE primary_key.contype = 'p' AND primary_key.conrelid = v_edge.conrelid;
            IF v_row_key IS NULL THEN
                RAISE EXCEPTION 'project purge primary key is missing';
            END IF;
            EXECUTE format(
                'INSERT INTO control_plane.project_purge_targets(transaction_id, relation_id, row_tid, row_key) '
                'SELECT $1, child.tableoid::oid, child.ctid, jsonb_build_array(%s) FROM %s child '
                'JOIN %s parent ON %s '
                'JOIN control_plane.project_purge_targets target ON '
                'target.transaction_id = $1 AND target.relation_id = $2 AND target.relation_id = parent.tableoid::oid '
                'AND target.row_tid = parent.ctid '
                'FOR UPDATE OF child ON CONFLICT DO NOTHING',
                v_row_key, v_edge.child_table, v_edge.parent_table, v_join)
            USING v_transaction_id, v_edge.confrelid;
            GET DIAGNOSTICS v_added = ROW_COUNT;
            v_cycle_added := v_cycle_added + v_added;
        END LOOP;
        EXIT WHEN v_cycle_added = 0;
    END LOOP;

    FOR v_table IN
        SELECT target.relation_id,
               format('%I.%I', namespace_row.nspname, class_row.relname) AS table_name
        FROM control_plane.project_purge_targets target
        JOIN pg_class class_row ON class_row.oid = target.relation_id
        JOIN pg_namespace namespace_row ON namespace_row.oid = class_row.relnamespace
        WHERE target.transaction_id = v_transaction_id
        GROUP BY target.relation_id, namespace_row.nspname, class_row.relname
        ORDER BY target.relation_id
    LOOP
        IF EXISTS (SELECT 1 FROM pg_attribute attribute_row
                   WHERE attribute_row.attrelid = v_table.relation_id
                     AND attribute_row.attname = 'organization_id' AND NOT attribute_row.attisdropped) THEN
            EXECUTE format(
                'SELECT EXISTS (SELECT 1 FROM %s victim '
                'JOIN control_plane.project_purge_targets target ON '
                'target.transaction_id = $1 AND target.relation_id = $3 AND target.relation_id = victim.tableoid::oid '
                'AND target.row_tid = victim.ctid '
                'WHERE victim.organization_id IS DISTINCT FROM $2)', v_table.table_name)
            INTO v_bad USING v_transaction_id, p_organization_id, v_table.relation_id;
            IF v_bad THEN
                RAISE EXCEPTION 'project purge crossed organization boundary';
            END IF;
        END IF;
        IF EXISTS (SELECT 1 FROM pg_attribute attribute_row
                   WHERE attribute_row.attrelid = v_table.relation_id
                     AND attribute_row.attname = 'project_id' AND NOT attribute_row.attisdropped) THEN
            EXECUTE format(
                'SELECT EXISTS (SELECT 1 FROM %s victim '
                'JOIN control_plane.project_purge_targets target ON '
                'target.transaction_id = $1 AND target.relation_id = $3 AND target.relation_id = victim.tableoid::oid '
                'AND target.row_tid = victim.ctid '
                'WHERE victim.project_id IS DISTINCT FROM $2)', v_table.table_name)
            INTO v_bad USING v_transaction_id, p_project_id, v_table.relation_id;
            IF v_bad THEN
                RAISE EXCEPTION 'project purge crossed project boundary';
            END IF;
        END IF;
    END LOOP;

    SELECT count(*) - 1 INTO v_deleted_rows
    FROM control_plane.project_purge_targets WHERE transaction_id = v_transaction_id;
    FOR v_table IN
        SELECT target.relation_id,
               format('%I.%I', namespace_row.nspname, class_row.relname) AS table_name
        FROM control_plane.project_purge_targets target
        JOIN pg_class class_row ON class_row.oid = target.relation_id
        JOIN pg_namespace namespace_row ON namespace_row.oid = class_row.relnamespace
        WHERE target.transaction_id = v_transaction_id
          AND target.relation_id <> 'control_plane.projects'::regclass::oid
        GROUP BY target.relation_id, namespace_row.nspname, class_row.relname
        ORDER BY target.relation_id
    LOOP
        SELECT string_agg(format('victim.%I = (target.row_key->>%s)::%s', key_attribute.attname,
            key_column.n-1, format_type(key_attribute.atttypid,key_attribute.atttypmod)), ' AND ' ORDER BY key_column.n)
        INTO v_row_key
        FROM pg_constraint primary_key
        CROSS JOIN LATERAL unnest(primary_key.conkey) WITH ORDINALITY AS key_column(number, n)
        JOIN pg_attribute key_attribute ON key_attribute.attrelid = primary_key.conrelid
          AND key_attribute.attnum = key_column.number
        WHERE primary_key.contype = 'p' AND primary_key.conrelid = v_table.relation_id;
        IF v_row_key IS NULL THEN
            RAISE EXCEPTION 'project purge primary key is missing';
        END IF;
        EXECUTE format(
            'DELETE FROM %s victim USING control_plane.project_purge_targets target '
            'WHERE target.transaction_id = $1 AND target.relation_id = $2 AND target.relation_id = victim.tableoid::oid '
            'AND %s', v_table.table_name, v_row_key)
        USING v_transaction_id, v_table.relation_id;
    END LOOP;
    DELETE FROM control_plane.projects
    WHERE id = p_project_id AND organization_id = p_organization_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'project purge target disappeared';
    END IF;
    SET CONSTRAINTS ALL IMMEDIATE;
    UPDATE control_plane.project_purge_receipts
    SET state = 'DONE', purged_at = statement_timestamp(), deleted_rows = v_deleted_rows
    WHERE project_id = p_project_id AND organization_id = p_organization_id;
    DELETE FROM control_plane.project_purge_targets WHERE transaction_id = v_transaction_id;
    DELETE FROM control_plane.project_purge_context WHERE transaction_id = v_transaction_id;
    RETURN v_deleted_rows;
END;
$function$

control_plane.guard_integration_approval.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_integration_approval_scope_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE cap jsonb; max_duration bigint; max_count bigint; lifetime_choices jsonb;
BEGIN
 IF NEW.version<>1 OR NEW.reserved_effects<>1 OR NEW.revoked_at IS NOT NULL OR NOT EXISTS(
  SELECT 1 FROM control_plane.runs root JOIN control_plane.subjects initiator ON initiator.id=root.initiated_by AND initiator.organization_id=root.organization_id
  JOIN control_plane.owner_gates gate ON gate.id=NEW.origin_gate_id AND gate.organization_id=root.organization_id AND gate.root_run_id=root.id AND gate.project_id IS NOT DISTINCT FROM NEW.project_id
  JOIN control_plane.integration_invocations invocation ON invocation.id=gate.integration_invocation_id AND invocation.organization_id=root.organization_id
  JOIN control_plane.run_nodes node ON node.id=invocation.node_id AND node.agent_id=NEW.agent_id
  WHERE root.id=NEW.root_run_id AND root.root_run_id=root.id AND root.organization_id=NEW.organization_id AND root.project_id IS NOT DISTINCT FROM NEW.project_id
   AND root.initiated_by=NEW.initiator_id AND gate.state='OPEN' AND invocation.state='WAITING_APPROVAL' AND invocation.approval_policy='HUMAN_SCOPED'
   AND invocation.connection_id=NEW.connection_id AND invocation.grant_id=NEW.grant_id AND invocation.grant_version=NEW.grant_version
   AND invocation.capability_key=NEW.capability_key AND invocation.definition_digest=NEW.definition_digest AND invocation.approval_scope_paths=NEW.scope_paths
   AND (NEW.scope_lifetime='ROOT_RUN' OR (initiator.kind='USER' AND initiator.active))
 ) THEN RAISE EXCEPTION 'integration approval scope owner binding is invalid'; END IF;
 SELECT value INTO cap FROM jsonb_array_elements(control_plane.integration_pinned_capabilities(NEW.connection_id)) value WHERE value->>'key'=NEW.capability_key;
 max_duration=COALESCE((cap #>> '{approvalScope,maxDurationSeconds}')::bigint,(cap #>> '{approvalScope,limits,durationSeconds}')::bigint,86400);
 max_count=COALESCE((cap #>> '{approvalScope,maxEffects}')::bigint,(cap #>> '{approvalScope,limits,maxEffects}')::bigint,100);
 lifetime_choices=COALESCE(cap #> '{approvalScope,allowedLifetimes}','["ROOT_RUN"]'::jsonb);
 IF cap IS NULL OR NEW.max_effects>max_count OR NEW.expires_at>clock_timestamp()+make_interval(secs=>max_duration)
  OR NOT (lifetime_choices ? NEW.scope_lifetime) THEN RAISE EXCEPTION 'integration approval scope exceeds pinned policy'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION control_plane.guard_integration_approval_scope_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF (to_jsonb(NEW)-'reserved_effects'-'revoked_at'-'version') IS DISTINCT FROM (to_jsonb(OLD)-'reserved_effects'-'revoked_at'-'version')
  OR NEW.reserved_effects<OLD.reserved_effects OR NEW.version<>OLD.version
  OR (OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at)
  OR (NEW.reserved_effects>OLD.reserved_effects AND (OLD.revoked_at IS NOT NULL OR OLD.expires_at<=clock_timestamp())) THEN
  RAISE EXCEPTION 'integration approval scope binding is immutable';
 END IF;
 IF NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
  NEW.revoked_at=clock_timestamp(); NEW.version=OLD.version+1;
 END IF;
 RETURN NEW;
END $function$

control_plane.guard_personal_credential_.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_personal_credential_test()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control_plane'
AS $function$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'personal credential test history cannot be deleted' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.state<>'DUE' OR NEW.generation<>0 OR NEW.version<>1 THEN
            RAISE EXCEPTION 'personal credential test initial state is invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.id,NEW.ref,NEW.organization_id,NEW.connection_id,NEW.binding_id,NEW.subject_id,NEW.credential_revision_id,NEW.input_schema_version,NEW.input_snapshot,NEW.created_at)
       IS DISTINCT FROM
       (OLD.id,OLD.ref,OLD.organization_id,OLD.connection_id,OLD.binding_id,OLD.subject_id,OLD.credential_revision_id,OLD.input_schema_version,OLD.input_snapshot,OLD.created_at) OR
       OLD.version=9223372036854775807 OR NEW.version<>OLD.version+1 OR NOT (
        (OLD.state='DUE' AND NEW.state='CLAIMED' AND NEW.generation=1) OR
        (OLD.state='DUE' AND NEW.state='CANCELLED' AND NEW.generation=0) OR
        (OLD.state='CLAIMED' AND NEW.state IN ('PROBING','FAILED','CANCELLED') AND NEW.generation=OLD.generation) OR
        (OLD.state='PROBING' AND NEW.state IN ('SUCCEEDED','FAILED','CANCELLED') AND NEW.generation=OLD.generation)
       ) OR (OLD.probe_admitted_at IS NOT NULL AND NEW.probe_admitted_at IS DISTINCT FROM OLD.probe_admitted_at) OR
       (OLD.probe_admitted_at IS NULL AND NEW.probe_admitted_at IS NOT NULL AND NOT (OLD.state='CLAIMED' AND NEW.state='PROBING')) OR
       (OLD.state='CLAIMED' AND NEW.state='PROBING' AND
        (NEW.lease_ref,NEW.fence_digest,NEW.workload_instance,NEW.lease_expires_at) IS DISTINCT FROM
        (OLD.lease_ref,OLD.fence_digest,OLD.workload_instance,OLD.lease_expires_at)) THEN
        RAISE EXCEPTION 'personal credential test transition is invalid' USING ERRCODE='23514';
    END IF;
    NEW.updated_at:=clock_timestamp();
    RETURN NEW;
END;
$function$

control_plane.guard_personal_integration.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_personal_integration_credential()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control_plane'
AS $function$
DECLARE
    credential_changed boolean;
    newly_revoked boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'personal integration credential history cannot be deleted' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'NOT_CONFIGURED' OR NEW.version <> 1 OR NEW.generation <> 1 OR
           NEW.credential_revision_id IS NOT NULL THEN
            RAISE EXCEPTION 'personal integration credential initial state is invalid' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.id, NEW.ref, NEW.organization_id, NEW.connection_id, NEW.subject_id, NEW.created_at)
       IS DISTINCT FROM
       (OLD.id, OLD.ref, OLD.organization_id, OLD.connection_id, OLD.subject_id, OLD.created_at) OR
       OLD.version = 9223372036854775807 OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'personal integration credential owner or version is invalid' USING ERRCODE = '23514';
    END IF;
    credential_changed := NEW.credential_revision_id IS DISTINCT FROM OLD.credential_revision_id;
    newly_revoked := NEW.state = 'REVOKED' AND OLD.state <> 'REVOKED';
    IF credential_changed OR newly_revoked THEN
        IF OLD.generation = 9223372036854775807 OR NEW.generation <> OLD.generation + 1 OR
           NEW.state NOT IN ('CHECK_REQUIRED', 'REVOKED') OR
           (credential_changed AND (NEW.state <> 'CHECK_REQUIRED' OR NEW.credential_revision_id IS NULL)) THEN
            RAISE EXCEPTION 'personal integration credential generation is invalid' USING ERRCODE = '23514';
        END IF;
        IF credential_changed AND OLD.credential_revision_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM control_plane.integration_personal_credential_revisions previous_revision
            JOIN control_plane.integration_personal_credential_revisions next_revision
              ON next_revision.binding_id = previous_revision.binding_id
             AND next_revision.organization_id = previous_revision.organization_id
             AND next_revision.revision > previous_revision.revision
            WHERE previous_revision.id = OLD.credential_revision_id
              AND next_revision.id = NEW.credential_revision_id
              AND previous_revision.binding_id = OLD.id
              AND previous_revision.organization_id = OLD.organization_id
        ) THEN
            RAISE EXCEPTION 'personal integration credential revision must advance' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.generation <> OLD.generation OR NOT (
        (OLD.state IN ('CHECK_REQUIRED', 'READY', 'INVALID') AND NEW.state = 'CHECKING') OR
        (OLD.state IN ('READY', 'INVALID') AND NEW.state = 'CHECK_REQUIRED') OR
        (OLD.state = 'CHECKING' AND NEW.state IN ('READY', 'INVALID', 'CHECK_REQUIRED'))
    ) THEN
        RAISE EXCEPTION 'personal integration credential transition is invalid' USING ERRCODE = '23514';
    END IF;
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
END;
$function$

control_plane.guard_ssh_compose_snapshot.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_ssh_compose_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
  IF OLD.ssh_compose_snapshot IS NOT NULL AND OLD.ssh_compose_snapshot IS DISTINCT FROM NEW.ssh_compose_snapshot THEN
    RAISE EXCEPTION 'SSH Compose snapshot is immutable';
  END IF;
  RETURN NEW;
END;
$function$

control_plane.guard_workflow_exception_e.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_workflow_exception_episodes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control_plane'
AS $function$
DECLARE old_count integer; new_count integer; previous jsonb; episode jsonb; immutable_keys text[];
        terminal boolean; published jsonb;
BEGIN
    IF TG_OP='DELETE' THEN
        IF OLD.workflow_exception_history<>'[]'::jsonb OR OLD.workflow_exception IS NOT NULL THEN
            IF NOT control_plane.project_purge_authorized() OR NOT EXISTS (
                SELECT 1 FROM control_plane.project_purge_targets target
                JOIN control_plane.project_purge_context context USING (transaction_id)
                WHERE target.transaction_id=pg_current_xact_id_if_assigned() AND context.backend_pid=pg_backend_pid()
                    AND target.relation_id='control_plane.runs'::regclass AND target.row_key=jsonb_build_array(OLD.id)
            ) THEN
                RAISE EXCEPTION 'workflow exception history requires authorized project purge'
                    USING ERRCODE='23514', CONSTRAINT='workflow_exception_delete_authority';
            END IF;
        END IF;
        RETURN OLD;
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.workflow_exception_history<>'[]'::jsonb OR NEW.workflow_exception IS NOT NULL THEN
            RAISE EXCEPTION 'workflow exception history must start empty' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    terminal:=NEW.state IN ('FAILED','CANCELLED');
    old_count:=jsonb_array_length(OLD.workflow_exception_history);
    IF terminal AND OLD.workflow_exception IS NOT NULL AND old_count>0 THEN
        episode:=OLD.workflow_exception_history->-1;
        IF episode->>'state' IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER') THEN
            episode:=episode||jsonb_build_object('state',CASE WHEN EXISTS (
                    SELECT 1 FROM control_plane.owner_gates decision_gate
                    WHERE decision_gate.id::text=episode->>'gateId' AND decision_gate.ref=episode->>'gateRef'
                        AND decision_gate.organization_id=NEW.organization_id AND decision_gate.root_run_id=NEW.id
                        AND decision_gate.project_id=NEW.project_id
                        AND decision_gate.state='REJECTED' AND decision_gate.decision='REJECT'
                ) THEN 'REJECTED' ELSE 'CANCELLED' END,
                'version',(episode->>'version')::bigint+1);
            NEW.workflow_exception_history:=jsonb_set(OLD.workflow_exception_history,ARRAY[(old_count-1)::text],episode);
            NEW.workflow_exception:=NULL;
        END IF;
    END IF;
    IF NEW.workflow_exception_history IS NOT DISTINCT FROM OLD.workflow_exception_history
       AND NEW.workflow_exception IS NOT DISTINCT FROM OLD.workflow_exception THEN
        IF NEW.state='SUCCEEDED' AND NEW.workflow_exception IS NOT NULL THEN
            RAISE EXCEPTION 'workflow recovery blocks successful root completion' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id IS DISTINCT FROM NEW.root_run_id OR jsonb_typeof(NEW.workflow_exception_history) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'workflow episodes belong to one root' USING ERRCODE='23514';
    END IF;
    SELECT version.spec INTO published FROM control_plane.workflow_versions version
    JOIN control_plane.workflows workflow ON workflow.id=version.workflow_id AND workflow.organization_id=version.organization_id
    WHERE version.id=NEW.workflow_version_id AND version.organization_id=NEW.organization_id
        AND workflow.project_id=NEW.project_id AND version.spec->>'ExecutionMode'='SERVER_DAG_V1';
    IF published IS NULL THEN RAISE EXCEPTION 'workflow episode requires pinned server policy' USING ERRCODE='23514'; END IF;
    new_count:=jsonb_array_length(NEW.workflow_exception_history);
    IF new_count<1 OR new_count>48 OR new_count<old_count OR new_count>old_count+1 OR EXISTS (
        SELECT 1 FROM jsonb_array_elements(OLD.workflow_exception_history) WITH ORDINALITY item(value,position)
        WHERE item.position<=LEAST(old_count,new_count-1) AND NEW.workflow_exception_history->(item.position::integer-1) IS DISTINCT FROM item.value
    ) THEN RAISE EXCEPTION 'workflow episode prefix is immutable' USING ERRCODE='23514'; END IF;
    episode:=NEW.workflow_exception_history->-1;
    IF jsonb_typeof(episode) IS DISTINCT FROM 'object'
       OR episode-ARRAY['stepKey','attempt','reason','originNodeId','finalNodeId','episode','version','state',
           'managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId','inputs','kind','reworkPlan']<>'{}'::jsonb
       OR NOT episode ?& ARRAY['stepKey','attempt','reason','originNodeId','finalNodeId','episode','version','state','inputs']
       OR episode->'episode' IS DISTINCT FROM to_jsonb(new_count)
       OR jsonb_typeof(episode->'inputs') IS DISTINCT FROM 'array'
       OR jsonb_array_length(episode->'inputs')>8
       OR jsonb_typeof(episode->'state') IS DISTINCT FROM 'string'
       OR jsonb_typeof(episode->'attempt') IS DISTINCT FROM 'number'
       OR jsonb_typeof(episode->'version') IS DISTINCT FROM 'number'
       OR jsonb_typeof(episode->'reason') IS DISTINCT FROM 'string'
       OR (episode->>'reason')!~'^[A-Z_]{1,96}$'
       OR episode->>'state' NOT IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER','RECOVERED','REJECTED','CANCELLED') THEN
        RAISE EXCEPTION 'workflow episode shape is invalid' USING ERRCODE='23514';
    END IF;
    IF (episode ? 'kind') IS DISTINCT FROM (episode ? 'reworkPlan')
        OR (episode ? 'kind' AND (episode->>'kind'<>'UPSTREAM_REWORK' OR published->>'ReworkPolicy' IS DISTINCT FROM 'OWNER_APPROVED_UPSTREAM_V1')) THEN
        RAISE EXCEPTION 'workflow rework requires the explicit published profile' USING ERRCODE='23514';
    END IF;
    IF new_count=old_count+1 AND episode ? 'kind' AND control_plane.workflow_upstream_plan_valid(NEW.organization_id,NEW.id,episode) IS NOT TRUE THEN
        RAISE EXCEPTION 'workflow upstream plan differs from exact published subjects' USING ERRCODE='23514';
    END IF;
    IF new_count=old_count+1 THEN
        IF old_count>0 AND (OLD.workflow_exception IS NOT NULL OR OLD.workflow_exception_history->-1->>'state' NOT IN ('RECOVERED','REJECTED','CANCELLED')) THEN
            RAISE EXCEPTION 'workflow episode already active' USING ERRCODE='23514';
        END IF;
        IF episode->'version' IS DISTINCT FROM '1'::jsonb OR episode->>'state'<>'PENDING_MANAGER'
           OR episode ?| ARRAY['managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId']
           OR (episode->>'attempt')::integer NOT BETWEEN 0 AND 4 OR NOT EXISTS (
            SELECT 1 FROM control_plane.run_nodes anchor
            JOIN control_plane.run_nodes physical ON physical.id::text=episode->>'finalNodeId'
                AND physical.organization_id=anchor.organization_id AND physical.root_run_id=anchor.root_run_id
            WHERE anchor.organization_id=NEW.organization_id AND anchor.root_run_id=NEW.id
                AND anchor.id::text=episode->>'originNodeId' AND anchor.workflow_step_origin_node_id IS NULL
                AND anchor.workflow_step_key=episode->>'stepKey'
                AND ((episode->>'attempt'='0' AND anchor.id=physical.id AND anchor.workflow_business_attempt=0
                    AND anchor.state='PLANNED' AND anchor.materialization_state='PLANNED')
                  OR (episode->>'attempt'<>'0' AND COALESCE(physical.workflow_step_origin_node_id,physical.id)=anchor.id
                    AND physical.workflow_business_attempt=(episode->>'attempt')::integer
                    AND physical.workflow_inputs=episode->'inputs'
                    AND jsonb_array_length(anchor.workflow_attempts)=(episode->>'attempt')::integer
                    AND anchor.workflow_attempts->-1->'provenance'->>'nodeId'=physical.id::text
                    AND (anchor.workflow_attempts->-1->>'reason'=episode->>'reason'
                         OR (episode->>'reason'='OWNER_CHANGES_REQUESTED' AND anchor.workflow_attempts->-1->>'accepted'='true'))))
        ) THEN RAISE EXCEPTION 'workflow episode requires exact current attempt' USING ERRCODE='23514'; END IF;
    ELSE
        previous:=OLD.workflow_exception_history->-1;
        immutable_keys:=ARRAY['version','state','managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId'];
        IF episode-immutable_keys IS DISTINCT FROM previous-immutable_keys
           OR episode->'version' IS DISTINCT FROM to_jsonb((previous->>'version')::bigint+1)
           OR NOT ((previous->>'state'='PENDING_MANAGER' AND episode->>'state' IN ('MANAGER_QUEUED','WAITING_OWNER'))
               OR (previous->>'state'='MANAGER_QUEUED' AND episode->>'state'='WAITING_OWNER')
               OR (previous->>'state'='WAITING_OWNER' AND episode->>'state'='RECOVERED')
               OR (terminal AND previous->>'state' IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER')
                   AND episode->>'state' IN ('REJECTED','CANCELLED')))
           OR EXISTS (SELECT 1 FROM unnest(ARRAY['managerNodeId','managerNodeRef','gateId','gateRef','recoveryNodeId']) pin
               WHERE previous ? pin AND episode->pin IS DISTINCT FROM previous->pin) THEN
            RAISE EXCEPTION 'workflow episode transition or pins changed' USING ERRCODE='23514';
        END IF;
    END IF;
    IF episode->>'state' IN ('PENDING_MANAGER','MANAGER_QUEUED','WAITING_OWNER') THEN
        IF NEW.workflow_exception IS DISTINCT FROM episode OR NEW.state NOT IN ('QUEUED','RUNNING','WAITING_HUMAN') THEN
            RAISE EXCEPTION 'workflow active episode pin differs' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.workflow_exception IS NOT NULL THEN RAISE EXCEPTION 'workflow terminal episode remains active' USING ERRCODE='23514'; END IF;
    IF episode ? 'managerNodeId' AND NOT EXISTS (
        SELECT 1 FROM control_plane.run_nodes node
        JOIN control_plane.agents agent ON agent.id=node.agent_id AND agent.organization_id=node.organization_id AND agent.project_id=NEW.project_id
        WHERE node.organization_id=NEW.organization_id AND node.root_run_id=NEW.id
            AND node.id::text=episode->>'managerNodeId' AND node.ref=episode->>'managerNodeRef'
            AND node.workflow_step_key='workflow.coordinator.exception.'||(episode->>'episode')
            AND node.workflow_business_attempt=0 AND agent.ref=published->>'CoordinatorAgentRef'
    ) THEN RAISE EXCEPTION 'workflow manager pin differs' USING ERRCODE='23514'; END IF;
    IF episode->>'state'='WAITING_OWNER' AND episode ? 'managerNodeId' AND NOT EXISTS (
        SELECT 1 FROM control_plane.run_nodes node
        JOIN control_plane.runtime_revisions revision ON revision.node_id=node.id AND revision.organization_id=node.organization_id
            AND revision.run_id=node.run_id AND revision.root_run_id=node.root_run_id AND revision.turn_id=node.turn_id
            AND revision.agent_id=node.agent_id AND revision.attempt=node.attempt
        JOIN control_plane.runtime_leases lease ON lease.runtime_revision_id=revision.id AND lease.organization_id=revision.organization_id
            AND lease.run_id=revision.run_id AND lease.node_id=node.id AND lease.generation=revision.generation AND lease.state='COMPLETED'
        WHERE node.organization_id=NEW.organization_id AND node.root_run_id=NEW.id AND node.id::text=episode->>'managerNodeId'
            AND node.state IN ('SUCCEEDED','FAILED')
    ) THEN RAISE EXCEPTION 'workflow manager is not completed' USING ERRCODE='23514'; END IF;
    IF episode->>'state'='WAITING_OWNER' AND NOT EXISTS (
        SELECT 1 FROM control_plane.owner_gates gate
        JOIN control_plane.run_nodes gate_node ON gate_node.id=gate.node_id AND gate_node.organization_id=gate.organization_id
        WHERE gate.organization_id=NEW.organization_id AND gate.root_run_id=NEW.id AND gate.project_id=NEW.project_id
            AND gate.id::text=episode->>'gateId' AND gate.ref=episode->>'gateRef' AND gate.state='OPEN'
            AND gate_node.parent_node_id::text=COALESCE(episode->>'managerNodeId',episode->>'finalNodeId')
    ) THEN RAISE EXCEPTION 'workflow recovery gate pin differs' USING ERRCODE='23514'; END IF;
    IF episode->>'state'='RECOVERED' AND NOT EXISTS (
        SELECT 1 FROM control_plane.run_nodes node
        JOIN control_plane.owner_gates gate ON gate.id::text=episode->>'gateId'
            AND gate.organization_id=NEW.organization_id AND gate.root_run_id=NEW.id AND gate.state='APPROVED'
        WHERE node.id::text=episode->>'recoveryNodeId' AND node.organization_id=NEW.organization_id AND node.root_run_id=NEW.id
            AND ((NOT episode ? 'kind'
                AND node.workflow_business_attempt=(episode->>'attempt')::integer+1
                AND COALESCE(node.workflow_step_origin_node_id,node.id)::text=episode->>'originNodeId'
                AND node.workflow_inputs=episode->'inputs' AND (episode->>'attempt')::integer<4)
              OR (episode->>'kind'='UPSTREAM_REWORK' AND node.workflow_rework_gate_id=gate.id
                AND node.workflow_business_attempt BETWEEN 2 AND 4
                AND COALESCE(episode->'reworkPlan'->>'blockReason','')=''
                AND EXISTS(SELECT 1 FROM jsonb_array_elements(episode->'reworkPlan'->'targets') member(value)
                    WHERE member.value->>'originNodeId'=node.workflow_step_origin_node_id::text
                        AND member.value->>'stepKey'=node.workflow_step_key
                        AND member.value->'nextAttempt'=to_jsonb(node.workflow_business_attempt))))
            AND (episode->>'episode')::integer<48
    ) THEN RAISE EXCEPTION 'workflow fresh recovery execution differs' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$function$

control_plane.protect_email_mailbox_gate.definition:
CREATE OR REPLACE FUNCTION control_plane.protect_email_mailbox_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND (NEW.mailbox_gate_required IS DISTINCT FROM OLD.mailbox_gate_required
  OR NEW.approval_policy IS DISTINCT FROM OLD.approval_policy OR NEW.grant_version IS DISTINCT FROM OLD.grant_version
  OR NEW.approval_scope_paths IS DISTINCT FROM OLD.approval_scope_paths) THEN
  RAISE EXCEPTION 'integration approval binding is immutable';
 END IF;
 IF NEW.mailbox_gate_required AND NOT EXISTS(SELECT 1 FROM control_plane.integration_connections c
   WHERE c.id=NEW.connection_id AND c.organization_id=NEW.organization_id AND c.definition_key='email') THEN
  RAISE EXCEPTION 'mailbox approval requires email owner connection';
 END IF;
 IF TG_OP='INSERT' AND NOT control_plane.integration_declared_policy_allowed(
   NEW.connection_id,NEW.capability_key,NEW.operation,NEW.risk,NEW.resource_kind,NEW.approval_policy,NEW.bounded_input) THEN
  RAISE EXCEPTION 'integration policy is not declared by pinned package';
 END IF;
 RETURN NEW;
END $function$

control_plane.protect_workflow_execution.definition:
CREATE OR REPLACE FUNCTION control_plane.protect_workflow_execution_clock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control_plane'
AS $function$
DECLARE
    specification jsonb;
    step text;
    seconds integer;
    started timestamptz;
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.execution_started_at IS NOT NULL OR NEW.execution_deadline_at IS NOT NULL
           OR NEW.execution_timeout_seconds IS NOT NULL OR NEW.execution_step_key IS NOT NULL THEN
            RAISE EXCEPTION 'workflow execution clock is assigned on first claim';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.execution_started_at IS NOT NULL THEN
        IF ROW(NEW.execution_started_at,NEW.execution_deadline_at,NEW.execution_timeout_seconds,NEW.execution_step_key,NEW.workflow_version_id)
           IS DISTINCT FROM ROW(OLD.execution_started_at,OLD.execution_deadline_at,OLD.execution_timeout_seconds,OLD.execution_step_key,OLD.workflow_version_id) THEN
            RAISE EXCEPTION 'workflow execution clock is immutable';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.execution_started_at IS NULL THEN
        IF NEW.execution_deadline_at IS NOT NULL OR NEW.execution_timeout_seconds IS NOT NULL OR NEW.execution_step_key IS NOT NULL THEN
            RAISE EXCEPTION 'workflow execution clock is incomplete';
        END IF;
        RETURN NEW;
    END IF;
    SELECT version.spec INTO STRICT specification FROM control_plane.workflow_versions version
    JOIN control_plane.runs root ON root.workflow_version_id=version.id
    WHERE root.id=NEW.root_run_id AND root.organization_id=NEW.organization_id
      AND root.project_id IS NOT DISTINCT FROM NEW.project_id
      AND NEW.workflow_version_id=version.id;
    IF NEW.id=NEW.root_run_id THEN
        step := ''; seconds := (specification->>'TimeoutSeconds')::integer;
    ELSE
        SELECT node.workflow_step_key INTO STRICT step FROM control_plane.run_nodes node
        WHERE node.run_id=NEW.id AND node.organization_id=NEW.organization_id AND node.type='AGENT_EXECUTION';
        SELECT (item->>'TimeoutSeconds')::integer INTO STRICT seconds
        FROM jsonb_array_elements(specification->'Steps') item WHERE item->>'Key'=step;
    END IF;
    IF seconds<1 OR seconds>(CASE WHEN step='' THEN 604800 ELSE 86400 END)
       OR NEW.state NOT IN ('QUEUED','RUNNING') THEN
        RAISE EXCEPTION 'workflow execution clock source is invalid';
    END IF;
    started := clock_timestamp();
    NEW.execution_started_at := started;
    NEW.execution_timeout_seconds := seconds;
    NEW.execution_step_key := step;
    NEW.execution_deadline_at := started+seconds*interval '1 second';
    RETURN NEW;
END $function$

control_plane.purge_project_database(uui.definition:
CREATE OR REPLACE FUNCTION control_plane.purge_project_database(p_organization_id uuid, p_project_id uuid, p_objects_digest text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
    v_transaction_id xid8;
    v_receipt control_plane.project_purge_receipts%ROWTYPE;
    v_project_ref text;
    v_nodes integer;
    v_node_fingerprint text;
    v_edges integer;
    v_edge_fingerprint text;
    v_edge record;
    v_table record;
    v_join text;
    v_row_key text;
    v_added integer;
    v_cycle_added integer;
    v_deleted_rows integer;
    v_bad boolean;
BEGIN
    SELECT * INTO v_receipt
    FROM control_plane.project_purge_receipts
    WHERE organization_id = p_organization_id AND project_id = p_project_id
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'project purge receipt is missing';
    END IF;
    IF v_receipt.state = 'DONE' THEN
        IF v_receipt.objects_digest IS DISTINCT FROM p_objects_digest THEN
            RAISE EXCEPTION 'project purge receipt digest changed';
        END IF;
        RETURN v_receipt.deleted_rows;
    END IF;
    IF v_receipt.state <> 'OBJECTS_CLEARED' OR
       v_receipt.objects_digest IS DISTINCT FROM p_objects_digest OR
       v_receipt.objects_cleared_at IS NULL THEN
        RAISE EXCEPTION 'project purge external cleanup is unverified';
    END IF;
    SELECT ref INTO v_project_ref FROM control_plane.projects
    WHERE id = p_project_id AND organization_id = p_organization_id
      AND lifecycle = 'PURGE_PENDING'
    FOR UPDATE;
    IF NOT FOUND OR v_project_ref IS DISTINCT FROM v_receipt.project_ref THEN
        RAISE EXCEPTION 'project purge target changed';
    END IF;
    IF control_plane.project_purge_inventory_digest(p_organization_id, p_project_id)
       IS DISTINCT FROM p_objects_digest THEN
        RAISE EXCEPTION 'project purge external inventory changed';
    END IF;

    WITH RECURSIVE nodes(relation_id) AS (
        SELECT 'control_plane.projects'::regclass::oid
        UNION
        SELECT constraint_row.conrelid FROM nodes
        JOIN pg_constraint constraint_row ON constraint_row.contype = 'f'
          AND constraint_row.confrelid = nodes.relation_id
        JOIN pg_namespace namespace_row ON namespace_row.oid = constraint_row.connamespace
          AND namespace_row.nspname = 'control_plane'
    )
    SELECT count(*),
           md5(string_agg(namespace_row.nspname || '.' || class_row.relname,
                          E'\n' ORDER BY namespace_row.nspname, class_row.relname))
    INTO v_nodes, v_node_fingerprint
    FROM nodes JOIN pg_class class_row ON class_row.oid = nodes.relation_id
    JOIN pg_namespace namespace_row ON namespace_row.oid = class_row.relnamespace;
    IF v_nodes <> 111 OR v_node_fingerprint <> '3eb558fae167872ba6bd17bc68f7a303' THEN
        RAISE EXCEPTION 'project purge table graph changed';
    END IF;
    WITH RECURSIVE nodes(relation_id) AS (
        SELECT 'control_plane.projects'::regclass::oid
        UNION
        SELECT constraint_row.conrelid FROM nodes
        JOIN pg_constraint constraint_row ON constraint_row.contype = 'f'
          AND constraint_row.confrelid = nodes.relation_id
        JOIN pg_namespace namespace_row ON namespace_row.oid = constraint_row.connamespace
          AND namespace_row.nspname = 'control_plane'
    )
    SELECT count(*), md5(string_agg(
        child_namespace.nspname || '.' || child_class.relname || '|' ||
        constraint_row.conname || '|' ||
        parent_namespace.nspname || '.' || parent_class.relname || '|' ||
        constraint_row.confdeltype::text,
        E'\n' ORDER BY child_namespace.nspname, child_class.relname, constraint_row.conname))
    INTO v_edges, v_edge_fingerprint
    FROM pg_constraint constraint_row
    JOIN pg_class child_class ON child_class.oid = constraint_row.conrelid
    JOIN pg_namespace child_namespace ON child_namespace.oid = child_class.relnamespace
    JOIN pg_class parent_class ON parent_class.oid = constraint_row.confrelid
    JOIN pg_namespace parent_namespace ON parent_namespace.oid = parent_class.relnamespace
    WHERE constraint_row.contype = 'f'
      AND constraint_row.confrelid IN (SELECT relation_id FROM nodes)
      AND constraint_row.conrelid IN (SELECT relation_id FROM nodes);
    IF v_edges <> 306 OR v_edge_fingerprint <> '19782286a860f9e05cdaad7b6e5f8ef3' THEN
        RAISE EXCEPTION 'project purge foreign-key graph changed';
    END IF;


    IF EXISTS (
      WITH RECURSIVE nodes(relation_id) AS (
        SELECT 'control_plane.projects'::regclass::oid UNION
        SELECT c.conrelid FROM nodes n JOIN pg_constraint c ON c.confrelid=n.relation_id
          AND c.contype='f' AND c.connamespace='control_plane'::regnamespace
      ) SELECT 1 FROM pg_constraint WHERE contype='f' AND confdeltype='a' AND NOT condeferrable
        AND conrelid IN(SELECT relation_id FROM nodes) AND confrelid IN(SELECT relation_id FROM nodes)
    ) THEN RAISE EXCEPTION 'project purge deferred foreign-key graph changed'; END IF;
    v_transaction_id := pg_current_xact_id();
    INSERT INTO control_plane.project_purge_context(transaction_id, backend_pid, project_id)
    VALUES (v_transaction_id, pg_backend_pid(), p_project_id);

    PERFORM control_plane.project_purge_recovery_prepare_purge(p_organization_id,p_project_id,p_objects_digest);

    UPDATE control_plane.audit_events event
    SET assistant_agent_id=NULL
    FROM control_plane.agents agent
    WHERE event.organization_id=p_organization_id AND event.assistant_agent_id=agent.id
      AND agent.organization_id=p_organization_id AND agent.project_id=p_project_id
      AND event.project_id IS DISTINCT FROM p_project_id;


    INSERT INTO control_plane.project_purge_targets(
        transaction_id, relation_id, row_tid, row_key
    )
    SELECT v_transaction_id, project.tableoid::oid, project.ctid,
           jsonb_build_array(project.id)
    FROM control_plane.projects project
    WHERE project.id = p_project_id AND project.organization_id = p_organization_id;
    SET CONSTRAINTS ALL DEFERRED;

    LOOP
        v_cycle_added := 0;
        FOR v_edge IN
            SELECT constraint_row.conrelid, constraint_row.confrelid,
                   constraint_row.conkey, constraint_row.confkey,
                   format('%I.%I', child_namespace.nspname, child_class.relname) AS child_table,
                   format('%I.%I', parent_namespace.nspname, parent_class.relname) AS parent_table
            FROM pg_constraint constraint_row
            JOIN pg_class child_class ON child_class.oid = constraint_row.conrelid
            JOIN pg_namespace child_namespace ON child_namespace.oid = child_class.relnamespace
            JOIN pg_class parent_class ON parent_class.oid = constraint_row.confrelid
            JOIN pg_namespace parent_namespace ON parent_namespace.oid = parent_class.relnamespace
            WHERE constraint_row.contype = 'f'
              AND child_namespace.nspname = 'control_plane'
              AND parent_namespace.nspname = 'control_plane'
              AND constraint_row.confrelid IN (
                  SELECT DISTINCT relation_id FROM control_plane.project_purge_targets
                  WHERE transaction_id = v_transaction_id)
            ORDER BY constraint_row.conrelid, constraint_row.conname
        LOOP
            SELECT string_agg(format('child.%I = parent.%I', child_attribute.attname,
                                     parent_attribute.attname), ' AND ' ORDER BY child_column.n)
            INTO v_join
            FROM unnest(v_edge.conkey) WITH ORDINALITY AS child_column(number, n)
            JOIN unnest(v_edge.confkey) WITH ORDINALITY AS parent_column(number, n)
              ON parent_column.n = child_column.n
            JOIN pg_attribute child_attribute ON child_attribute.attrelid = v_edge.conrelid
              AND child_attribute.attnum = child_column.number
            JOIN pg_attribute parent_attribute ON parent_attribute.attrelid = v_edge.confrelid
              AND parent_attribute.attnum = parent_column.number;
            IF v_join IS NULL THEN
                RAISE EXCEPTION 'project purge foreign-key columns changed';
            END IF;
            SELECT string_agg(format('child.%I', key_attribute.attname), ', ' ORDER BY key_column.n)
            INTO v_row_key
            FROM pg_constraint primary_key
            CROSS JOIN LATERAL unnest(primary_key.conkey) WITH ORDINALITY AS key_column(number, n)
            JOIN pg_attribute key_attribute ON key_attribute.attrelid = primary_key.conrelid
              AND key_attribute.attnum = key_column.number
            WHERE primary_key.contype = 'p' AND primary_key.conrelid = v_edge.conrelid;
            IF v_row_key IS NULL THEN
                RAISE EXCEPTION 'project purge primary key is missing';
            END IF;
            EXECUTE format(
                'INSERT INTO control_plane.project_purge_targets(transaction_id, relation_id, row_tid, row_key) '
                'SELECT $1, child.tableoid::oid, child.ctid, jsonb_build_array(%s) FROM %s child '
                'JOIN %s parent ON %s '
                'JOIN control_plane.project_purge_targets target ON '
                'target.transaction_id = $1 AND target.relation_id = $2 AND target.relation_id = parent.tableoid::oid '
                'AND target.row_tid = parent.ctid '
                'FOR UPDATE OF child ON CONFLICT DO NOTHING',
                v_row_key, v_edge.child_table, v_edge.parent_table, v_join)
            USING v_transaction_id, v_edge.confrelid;
            GET DIAGNOSTICS v_added = ROW_COUNT;
            v_cycle_added := v_cycle_added + v_added;
        END LOOP;
        EXIT WHEN v_cycle_added = 0;
    END LOOP;

    FOR v_table IN
        SELECT target.relation_id,
               format('%I.%I', namespace_row.nspname, class_row.relname) AS table_name
        FROM control_plane.project_purge_targets target
        JOIN pg_class class_row ON class_row.oid = target.relation_id
        JOIN pg_namespace namespace_row ON namespace_row.oid = class_row.relnamespace
        WHERE target.transaction_id = v_transaction_id
        GROUP BY target.relation_id, namespace_row.nspname, class_row.relname
        ORDER BY target.relation_id
    LOOP
        IF EXISTS (SELECT 1 FROM pg_attribute attribute_row
                   WHERE attribute_row.attrelid = v_table.relation_id
                     AND attribute_row.attname = 'organization_id' AND NOT attribute_row.attisdropped) THEN
            EXECUTE format(
                'SELECT EXISTS (SELECT 1 FROM %s victim '
                'JOIN control_plane.project_purge_targets target ON '
                'target.transaction_id = $1 AND target.relation_id = $3 AND target.relation_id = victim.tableoid::oid '
                'AND target.row_tid = victim.ctid '
                'WHERE victim.organization_id IS DISTINCT FROM $2)', v_table.table_name)
            INTO v_bad USING v_transaction_id, p_organization_id, v_table.relation_id;
            IF v_bad THEN
                RAISE EXCEPTION 'project purge crossed organization boundary';
            END IF;
        END IF;
        IF EXISTS (SELECT 1 FROM pg_attribute attribute_row
                   WHERE attribute_row.attrelid = v_table.relation_id
                     AND attribute_row.attname = 'project_id' AND NOT attribute_row.attisdropped) THEN
            EXECUTE format(
                'SELECT EXISTS (SELECT 1 FROM %s victim '
                'JOIN control_plane.project_purge_targets target ON '
                'target.transaction_id = $1 AND target.relation_id = $3 AND target.relation_id = victim.tableoid::oid '
                'AND target.row_tid = victim.ctid '
                'WHERE victim.project_id IS DISTINCT FROM $2)', v_table.table_name)
            INTO v_bad USING v_transaction_id, p_project_id, v_table.relation_id;
            IF v_bad THEN
                RAISE EXCEPTION 'project purge crossed project boundary';
            END IF;
        END IF;
    END LOOP;

    SELECT count(*) - 1 INTO v_deleted_rows
    FROM control_plane.project_purge_targets WHERE transaction_id = v_transaction_id;
    FOR v_table IN
        SELECT target.relation_id,
               format('%I.%I', namespace_row.nspname, class_row.relname) AS table_name
        FROM control_plane.project_purge_targets target
        JOIN pg_class class_row ON class_row.oid = target.relation_id
        JOIN pg_namespace namespace_row ON namespace_row.oid = class_row.relnamespace
        WHERE target.transaction_id = v_transaction_id
          AND target.relation_id <> 'control_plane.projects'::regclass::oid
        GROUP BY target.relation_id, namespace_row.nspname, class_row.relname
        ORDER BY target.relation_id
    LOOP
        SELECT string_agg(format('victim.%I = (target.row_key->>%s)::%s', key_attribute.attname,
            key_column.n-1, format_type(key_attribute.atttypid,key_attribute.atttypmod)), ' AND ' ORDER BY key_column.n)
        INTO v_row_key
        FROM pg_constraint primary_key
        CROSS JOIN LATERAL unnest(primary_key.conkey) WITH ORDINALITY AS key_column(number, n)
        JOIN pg_attribute key_attribute ON key_attribute.attrelid = primary_key.conrelid
          AND key_attribute.attnum = key_column.number
        WHERE primary_key.contype = 'p' AND primary_key.conrelid = v_table.relation_id;
        IF v_row_key IS NULL THEN
            RAISE EXCEPTION 'project purge primary key is missing';
        END IF;
        EXECUTE format(
            'DELETE FROM %s victim USING control_plane.project_purge_targets target '
            'WHERE target.transaction_id = $1 AND target.relation_id = $2 AND target.relation_id = victim.tableoid::oid '
            'AND %s', v_table.table_name, v_row_key)
        USING v_transaction_id, v_table.relation_id;
    END LOOP;
    DELETE FROM control_plane.projects
    WHERE id = p_project_id AND organization_id = p_organization_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'project purge target disappeared';
    END IF;
    SET CONSTRAINTS ALL IMMEDIATE;
    UPDATE control_plane.project_purge_receipts
    SET state = 'DONE', purged_at = statement_timestamp(), deleted_rows = v_deleted_rows
    WHERE project_id = p_project_id AND organization_id = p_organization_id;
    DELETE FROM control_plane.project_purge_targets WHERE transaction_id = v_transaction_id;
    DELETE FROM control_plane.project_purge_context WHERE transaction_id = v_transaction_id;
    RETURN v_deleted_rows;
END;
$function$

control_plane.guard_personal_credential_.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_personal_credential_test()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control_plane'
AS $function$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'personal credential test history cannot be deleted' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.state<>'DUE' OR NEW.generation<>0 OR NEW.version<>1 THEN
            RAISE EXCEPTION 'personal credential test initial state is invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.id,NEW.ref,NEW.organization_id,NEW.connection_id,NEW.binding_id,NEW.subject_id,NEW.credential_revision_id,NEW.input_schema_version,NEW.input_snapshot,NEW.created_at)
       IS DISTINCT FROM
       (OLD.id,OLD.ref,OLD.organization_id,OLD.connection_id,OLD.binding_id,OLD.subject_id,OLD.credential_revision_id,OLD.input_schema_version,OLD.input_snapshot,OLD.created_at) OR
       OLD.version=9223372036854775807 OR NEW.version<>OLD.version+1 OR NOT (
        (OLD.state='DUE' AND NEW.state='CLAIMED' AND NEW.generation=1) OR
        (OLD.state='DUE' AND NEW.state='CANCELLED' AND NEW.generation=0) OR
        (OLD.state='CLAIMED' AND NEW.state IN ('PROBING','FAILED','CANCELLED') AND NEW.generation=OLD.generation) OR
        (OLD.state='PROBING' AND NEW.state IN ('SUCCEEDED','FAILED','CANCELLED') AND NEW.generation=OLD.generation)
       ) OR (OLD.probe_admitted_at IS NOT NULL AND NEW.probe_admitted_at IS DISTINCT FROM OLD.probe_admitted_at) OR
       (OLD.probe_admitted_at IS NULL AND NEW.probe_admitted_at IS NOT NULL AND NOT (OLD.state='CLAIMED' AND NEW.state='PROBING')) OR
       (OLD.state='CLAIMED' AND NEW.state='PROBING' AND
        (NEW.lease_ref,NEW.fence_digest,NEW.workload_instance,NEW.lease_expires_at) IS DISTINCT FROM
        (OLD.lease_ref,OLD.fence_digest,OLD.workload_instance,OLD.lease_expires_at)) THEN
        RAISE EXCEPTION 'personal credential test transition is invalid' USING ERRCODE='23514';
    END IF;
    NEW.updated_at:=clock_timestamp();
    RETURN NEW;
END;
$function$

control_plane.guard_personal_integration.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_personal_integration_credential()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'control_plane'
AS $function$
DECLARE
    credential_changed boolean;
    newly_revoked boolean;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'personal integration credential history cannot be deleted' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.state <> 'NOT_CONFIGURED' OR NEW.version <> 1 OR NEW.generation <> 1 OR
           NEW.credential_revision_id IS NOT NULL THEN
            RAISE EXCEPTION 'personal integration credential initial state is invalid' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.id, NEW.ref, NEW.organization_id, NEW.connection_id, NEW.subject_id, NEW.created_at)
       IS DISTINCT FROM
       (OLD.id, OLD.ref, OLD.organization_id, OLD.connection_id, OLD.subject_id, OLD.created_at) OR
       OLD.version = 9223372036854775807 OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'personal integration credential owner or version is invalid' USING ERRCODE = '23514';
    END IF;
    credential_changed := NEW.credential_revision_id IS DISTINCT FROM OLD.credential_revision_id;
    newly_revoked := NEW.state = 'REVOKED' AND OLD.state <> 'REVOKED';
    IF credential_changed OR newly_revoked THEN
        IF OLD.generation = 9223372036854775807 OR NEW.generation <> OLD.generation + 1 OR
           NEW.state NOT IN ('CHECK_REQUIRED', 'REVOKED') OR
           (credential_changed AND (NEW.state <> 'CHECK_REQUIRED' OR NEW.credential_revision_id IS NULL)) THEN
            RAISE EXCEPTION 'personal integration credential generation is invalid' USING ERRCODE = '23514';
        END IF;
        IF credential_changed AND OLD.credential_revision_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM control_plane.integration_personal_credential_revisions previous_revision
            JOIN control_plane.integration_personal_credential_revisions next_revision
              ON next_revision.binding_id = previous_revision.binding_id
             AND next_revision.organization_id = previous_revision.organization_id
             AND next_revision.revision > previous_revision.revision
            WHERE previous_revision.id = OLD.credential_revision_id
              AND next_revision.id = NEW.credential_revision_id
              AND previous_revision.binding_id = OLD.id
              AND previous_revision.organization_id = OLD.organization_id
        ) THEN
            RAISE EXCEPTION 'personal integration credential revision must advance' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.generation <> OLD.generation OR NOT (
        (OLD.state IN ('CHECK_REQUIRED', 'READY', 'INVALID') AND NEW.state = 'CHECKING') OR
        (OLD.state IN ('READY', 'INVALID') AND NEW.state = 'CHECK_REQUIRED') OR
        (OLD.state = 'CHECKING' AND NEW.state IN ('READY', 'INVALID', 'CHECK_REQUIRED'))
    ) THEN
        RAISE EXCEPTION 'personal integration credential transition is invalid' USING ERRCODE = '23514';
    END IF;
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
END;
$function$

control_plane.guard_ssh_compose_snapshot.definition:
CREATE OR REPLACE FUNCTION control_plane.guard_ssh_compose_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
